INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('voidwalker','Voidwalker','traveller','legitch',NULL,'','SCP Fragmented Veil','{"slug":"voidwalker","name":"Voidwalker","team":"traveller","ability":"You gain the vote tokens others use & might gain the abilities (once, you learn what) others lose.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-048 is a classification given superstition by foundation personnel for objects which disappear or get lost too often - here is where they ended up.","summaryBullets":["When a vote token is used by another player, the Voidwalker gains that vote token instead of it being lost forever.","The Voidwalker is able to append multiple votes on a given nomination by consuming their vote tokens on it.","When a player dies, the Voidwalker might immediately gain their ability and learn what it is.","If the player died during the day, the Voidwalker learns the ability privately as soon as possible, typically come dusk.","If any player loses their ability through any other method besides death {{i|(ex. Preacher)}}, the Voidwalker can still get their ability, but will revoke it upon that ability coming back."],"howToRun":["When a vote token is used by another player, transfer the vote token to the Voidwalker {{i|(it is still used by the original caster)}}.","When the Voidwalker votes, they may use one of their vote tokens to add an extra vote to the current nomination.","When any player dies and the Voidwalker doesn''t have another player''s ability, you may place their character token by the Voidwalkers character token. Treat the Voidwalker as if they had this character ability, as well as their Voidwalker ability.","As soon as possible {{i|(that night, or if already occuring during the night)}}, wake the Voidwalker. Show them the character token they gained. Put the Voidwalker to sleep."],"iconBy":"le_nuberto","firstNight":0,"otherNight":7.01413,"setup":false,"otherNightReminder":"If the Voidwalker gained an ability today: Wake the Voidwalker and show them the token of the ability they gained. Put the Voidwalker back to sleep.","art":"art/voidwalker.png","jsonId":"voidwalker_scp_fragmented_veil","curata":false}','scp-fragmented-veil/voidwalker','published',datetime('now'),datetime('now')),
('two-spirit','Two-Spirit','traveller','legitch',NULL,'','SCP Fragmented Veil','{"slug":"two-spirit","name":"Two-Spirit","team":"traveller","ability":"Each night*, choose a player: they become a character of the same alignment & all learn what set it''s from if it''s off-script.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-113 is a rock that forcefully changes the sex of whoever grabs it, changing them into a whole new person.","summaryBullets":["Each night except the first, the Two-Spirit chooses a player to transform into another. Neither player will know what the resulting character is... until it''s too late.","Additionally, the Storyteller may choose to instead bring in an off-script character into the game, in-which all players which set this character came from, and will be able to prepare for it.","The Two-Spirit can only change a player''s character into that which is on the same alignment, which means good players must become Townsfolk or Outsiders, whilst evil players must become Minions and Demons.","Typically, if the Two-Spirit is evil, they''ll be transforming Townsfolk into Outsiders more often."],"howToRun":["Each night, wake the Two-Spirit. The Two-Spirit points at any player. Put the Two-Spirit to sleep. Wake the chosen player. Show them the **YOU ARE** info token, then their new character token, then put them to sleep. Replace their old character token with the new character token. If the character isn''t from this script however, say that the Two-Spirit has used their ability and transformed a character into one from a different set, also name this set in particular."],"tips":["It''s recommended that you shouldn''t make a Minion become a Demon, or a Demon become a Minion, unless the circumstances for which allow the game to continue or persist without an unbalanced line-up of characters for the evil team. However, if the good team is winning quite convincingly and the evil team will surely lose soon, you can make a remaining Minion become the Demon whilst keeping the original one."],"iconBy":"le_nuberto","customBoxes":[{"title":"Alternative JSON","content":"For if you want the Demon to be able to agree to a change and possibly faking the alert to all players whilst secretly not being affected.\n\n**Two-Spirit █-** (Traveller)\nEach night*, choose a player: they become a character of the same alignment & all learn what set it''s from if it''s off-script. The Demon might be unaffected.\n\n**Other nights:** The Two-Spirit points to a player. Wake the player and show them the ''You are'' card and the relevant character token. If the character is off-script, announce that the Two-Spirit has used their ability and an off-script character was brought in - also note down which specific set they came from.\n**Credit:** Ability: @legitch. Image: @le_nuberto"}],"firstNight":0,"otherNight":2.113,"setup":false,"otherNightReminder":"The Two-Spirit points to a player. Wake the player and show them the ''You are'' card and the relevant character token. If the character is off-script, announce that the Two-Spirit has used their ability and an off-script character was brought in - also note down which specific set they came from.","art":"art/two-spirit.png","jsonId":"twospirit_scp_fragmented_veil","curata":false}','scp-fragmented-veil/two-spirit','published',datetime('now'),datetime('now')),
('sugar-rush','Sugar Rush','traveller','legitch',NULL,'','SCP Fragmented Veil','{"slug":"sugar-rush","name":"Sugar Rush","team":"traveller","ability":"Each night*, choose a player: if they agree, their ability works twice until tomorrow, then, they die, no matter what.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Sugar Rush (SCP-207) is a cola bottle that increases motor functionality and biological speed, even if the host body can''t handle it, and will die from it.","summaryBullets":["The Sugar Rush themselves choose which player that want to affect, and the chosen player chooses whether or not to accept.","A chosen player that accepts the Sugar Rush''s ability might act thrice that night, and might receive true info, but they always die regardless.","If the affected player is acting thrice, then they do so at the normal time. If they would normally wake at night, they act, go to sleep, then wake to act again. If they have already used a “once per game” ability, they may use that ability again. If they have a “once per game” ability but have not used it yet, they may use it twice before dusk."],"howToRun":["Each night except the first, if theres a player marked **SPEED!!!**, they **die** - mark them with the **DEAD** reminder token. Wake the Sugar Rush. The Sugar Rush points at any player. Put the Sugar Rush to sleep. Wake the chosen player, show them the THIS CHARACTER SELECTED YOU'' info token, then the Sugar Rush token. That player either nods their head yes or shakes their head no. Put that player to sleep.","If they shook their head no, then nothing happens. Continue with the night phase.","If they nodded their head yes, mark that player with the **SPEED!!!** reminder.","A player marked **SPEED!!!** acts twice at the appropriate time. If the ability is optional, they may use it twice. If it is mandatory, they must use it twice. Use the Sugar Rush’s **?** reminders if needed, to substitute for the character’s own reminders."],"iconBy":"le_nuberto","customBoxes":[{"title":"In the almanac JSON","content":"**Other nights:** The player who accepted the Sugar Rush''s ability dies (if any). The Sugar Rush points at any player. Then, put the Sugar Rush to sleep. Wake the chosen player, show them the ''This character selected you'' token, then the Sugar Rush token. That player either nods their head yes or shakes their head no. If they nodded their head yes, activate their ability twice until dusk."}],"firstNight":0,"otherNight":0.0207,"reminders":["Speed!!!","Dead","?","?","?"],"setup":false,"otherNightReminder":"The Sugar Rush points at any player. Then, put the Sugar Rush to sleep. Wake the chosen player, show them the ''This character selected you'' token, then the Sugar Rush token. That player either nods their head yes or shakes their head no. If they nodded their head yes, you may choose to activate their ability up to thrice when they next wake. That player dies afterwards.","art":"art/sugar-rush.png","jsonId":"sugarrush_scp_fragmented_veil","curata":false}','scp-fragmented-veil/sugar-rush','published',datetime('now'),datetime('now')),
('hanged-king','Hanged King','traveller','legitch',NULL,'','SCP Fragmented Veil','{"slug":"hanged-king","name":"Hanged King","team":"traveller","ability":"Publicly ask, and you might receive (once per day & all players learn what it is). On your 3rd declined request, you are exiled.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Hanged King (SCP-701) may ask permission from the court king if they may jest around.","summaryBullets":["The Hanged King''s current impact on the game can be anything they desire and wish for, provided it''s accepted by the Storyteller.","After the Hanged King makes their request, the Storyteller is free to append any additional statements, effects, triggers, or conditions to the request, but they are not allowed to change the request''s base component.","The Storyteller may accept or decline their proposal for any reason, regardless of how generic or detailed it was.","When a request is declined, the Storyteller is allowed to provide any insight into why it was declined {{i|(\"It is too overpowered for the good team\", \"I don''t want to bring an additional evil into this game\", \"This goes against the spirit of X\", etc...)}}.","The Hanged King''s exile cannot be prevented on their third declined request."],"howToRun":["During the day, the Hanged King can publicly declare that they wish to use their ability, and what their request is. It may be as detailed as possible, or be very generic and up to interpretation by the Storyteller.","If you approve of it, grant the request, and publicly declare what the results of the request are. There can only be one approval per day. Use the Hanged King''s **???**, **!!!**, and **...** reminders if you need to.","If you decline the request, publicly declare that the request was declined. If the Hanged King is marked with the **2ND DECLINED** reminder token, they are immediately exiled, if the Hanged King is marked with the **1ST DECLINED** reminder token, instead replace it with the **2ND DECLINED** reminder token, if the Hanged King is not marked with either reminder token, mark them with the **1ST DECLINED** reminder token."],"examples":["During the day, the Hanged King requests: \"I request some drunkenness amongst players\". The Storyteller approves of this request as it is both generic and not necessarily sided towards any alignment, so they declare it as **{{i|\"Until dawn, 2 Townsfolk are drunk if the Hanged King is evil, or 1 Minion is drunk if the Hanged King is good.\"}}**","The Hanged King requests: \"I request for the Demon to die.\" Since the base component of this request is too good-oriented, the Storyteller instead flat out denies it and strikes the Hanged King.","The Hanged King requests: \"I request the Artist gets another charge of their ability.\" As the base component of this request is good-oriented {{i|(but not to an absurd degree as the previous example)}}, the Storyteller approves of this request, but modifies & declares the final result as **{{i|\"The Artist (if in-play) receives another charge of their ability, but if the Hanged King is evil, any consult they make might receive arbitrary information.\"}}**","The Hanged King requests: \"I request that I get the Amnesiac''s ability.\" Whilst the base component of this request is not sided towards any alignment, it goes against the spirit of the Hanged King''s activities & effects being public, thus the Storyteller denies it and strikes the Hanged King."],"iconBy":"le_nuberto","customBoxes":[{"title":"Alternative JSON","content":"For if you want a happy and healthy Hanged King in your household.\n\n**Hanged King █+** (Traveller)\nPublicly ask, and you might receive (once per day & all players learn what it is). On your 3rd declined request, you are exiled. You are sober & healthy.\n\n**Reminders:** ???, !!!, ..., 1st declined, 2nd declined\n**Credit:** Ability: @legitch. Image: @le_nuberto"}],"firstNight":0,"otherNight":0,"reminders":["???","!!!","...","1st declined","2nd declined"],"setup":false,"art":"art/hanged-king.png","jsonId":"hangedking_scp_fragmented_veil","curata":false}','scp-fragmented-veil/hanged-king','published',datetime('now'),datetime('now')),
('encyclopediac','Encyclopediac','traveller','legitch',NULL,'','SCP Fragmented Veil','{"slug":"encyclopediac","name":"Encyclopediac","team":"traveller","ability":"Each night*, a player might become a character you mentioned today that''s unhelpful to them.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-1025 is a book that causes any reader to receive the disease they learn about. Seemingly, this book has strange effects in Ravenswood Bluff.","summaryBullets":["The Encyclopediac''s ability only triggers if they mentioned a character the previous day.","This includes mentioning a group of characters, mentioning them in passing, or referring to multiple via ability effects.","Not every night will a player be transformed into another character should the Encyclopediac mention a character that day.","When a character transformation occurs, an \"unhelpful\" character would one whose ability can''t help but disrupt that player''s team into an unfavorable position, but can generally be any character whose ability just doesn''t help their team advance forward.","There is nothing stopping the Storyteller from creating duplicate characters if they are able to."],"howToRun":["When you hear the Encyclopediac mention any character, you may choose to mark that character on the character sheet with the **SAID** reminder token.","Each night except the first, you may choose a player. Wake the chosen player. Show them the **YOU ARE** info token, then their new character token, then put them to sleep. Replace their old character token with the new character token. You may need to turn character tokens upside-down to remind you that a player’s alignment is opposite to the colour of the token. You may need to remind the player that their alignment is unchanged, by giving a thumbs-up or thumbs-down."],"iconBy":"le_nuberto","firstNight":0,"otherNight":2.1025,"reminders":["Said"],"setup":false,"otherNightReminder":"Wake a player, show them the ''You are'' card and the relevant character token.","art":"art/encyclopediac.png","jsonId":"encyclopediac_scp_fragmented_veil","curata":false}','scp-fragmented-veil/encyclopediac','published',datetime('now'),datetime('now')),
('dissociative','Dissociative','traveller','legitch',NULL,'','SCP Fragmented Veil','{"slug":"dissociative","name":"Dissociative","team":"traveller","ability":"A, if B, choose C1: C2. D. E. The Storyteller chooses who creates which section (B, D, & E optional), they also get the final say.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Dissociative (SCP-2020) is an alien that can''t seem to make up what their origin is, or for that matter, their own ability.","summaryBullets":["When the Dissociative travels in, 5 people will be constructing what their ability is from the ground up.","The Dissociative''s ability is composed of 5 aspects: The event (A), the condition (B), the targets of choice and the ability''s actions (C1 and C2), statement/clause/secondary-ability #1 (D), and statement/clause/tertiary-ability #2 (E).","The Storyteller chooses who is assigned to what ability, one by one. Other players not chosen are allowed to influence that player however, whether they beg, plead, ██████ their ████, ████ in █████ █████, or perform a ███████.","B, D, and E are completely optional, and may be skipped by the choice of whomever is assigned to it.","C2 cannot have multiple rules on top of it - additional conditions, abilities, or noted effects must be a part of D and/or E respectively.","Alongside all players, the Storyteller and even spectators with knowledge of the game are all viable candidates to contribute to the Dissociative''s ability.","After each aspect is created, the Storyteller then gets the final say on what the ability is."],"howToRun":["When the Dissociative travels in, start the process of creating the Dissociative''s ability. The Dissociative is made up of 5 aspects: The event (A), the condition (B), the targets of choice and the ability''s actions (C1 and C2), statement/clause/secondary-ability #1 (D), and statement/clause/tertiary-ability #2 (E). For each of these aspects, choose **anyone** you want and think would be able to take on the task, including yourself, or even a spectator. They declare what they want the aspect to be, or they have the option to skip it if its either B, D, or E {{i|(note that other players are allowed to talk with that player to influence their decision)}}. C2 cannot have multiple rules on top of it - additional conditions, abilities, or noted effects must be a part of D and//or E respectively. After they make the aspect, you may choose to modify it however you see it, whether to fit the correct wording, or to create a balanced ability. Once all aspects are done, write down the Dissociative''s ability on a piece of paper or on a phone, then publicly declare it to the whole group. Use the Dissociative’s **?** reminders if you need to."],"tips":["Be aware that the Dissociative is best run in a social and casual environment, as most of the fun of this character comes from everyone scrambling to make a coherent ability, and then rolling with what they made. It''s also not a bad idea to impose a time limit on deciding what an aspect of an ability should be - the more stressed out they are, the funnier it is. {{i|That''s a Legitch guarantee!™}}"],"iconBy":"le_nuberto","firstNight":0,"otherNight":0,"reminders":["?","?","?"],"setup":false,"art":"art/dissociative.png","jsonId":"dissociative_scp_fragmented_veil","curata":false}','scp-fragmented-veil/dissociative','published',datetime('now'),datetime('now'));
